import app from 'flarum/forum/app';
import PollGroupControls from '../utils/PollGroupControls';
export default class PollGroupFormState {
  loading = false;
  deleting = false;
  static createNewPollGroup() {
    const pollGroup = app.store.createRecord('poll_groups');
    pollGroup.pushAttributes({
      name: ''
    });
    return pollGroup;
  }
  constructor(pollGroup) {
    this.pollGroup = pollGroup || PollGroupFormState.createNewPollGroup();
  }
  async save(data) {
    this.loading = true;
    m.redraw();
    try {
      this.pollGroup = await this.pollGroup.save(data);
    } finally {
      this.loading = false;
      m.redraw();
    }
  }
  async delete() {
    this.loading = true;
    m.redraw();
    try {
      await PollGroupControls.deleteAction(this.pollGroup);
      this.deleting = !this.pollGroup.exists;
    } finally {
      this.loading = false;
      m.redraw();
    }
  }
}
flarum.reg.add('fof-polls', 'forum/states/PollGroupFormState', PollGroupFormState);