import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Placeholder from 'flarum/common/components/Placeholder';
import ItemList from 'flarum/common/utils/ItemList';
import PollShowcaseItem from './PollShowcaseItem';
const EMPTY_KEY = {
  active: 'no-active-polls',
  ended: 'no-recent-polls'
};
export default class PollShowcase extends Component {
  view() {
    return m("div", {
      className: "PollShowcase"
    }, this.section('active', this.attrs.activeState, false), this.section('ended', this.attrs.endedState, true));
  }
  section(name, state, loadMore) {
    const items = this.pollItems(name, state).toArray();
    return m("div", {
      className: `PollShowcase-section PollShowcase-section--${name}`
    }, m("h2", {
      className: "PollShowcase-title"
    }, app.translator.trans(`fof-polls.forum.showcase.${name}-polls`)), items.length ? items : m(Placeholder, {
      text: app.translator.trans(`fof-polls.forum.showcase.${EMPTY_KEY[name]}`)
    }), loadMore && state.hasNext() && m(Button, {
      className: "Button",
      loading: state.isLoadingNext(),
      onclick: () => state.loadNext()
    }, app.translator.trans('fof-polls.forum.polls_list.load_more_button')));
  }
  pollItems(name, state) {
    const items = new ItemList();
    if (state.isLoading()) {
      items.add('loading', m(LoadingIndicator, {
        size: "large"
      }));
      return items;
    }
    state.getPages().forEach(page => {
      page.items.forEach(poll => {
        items.add(`poll-${name}-${poll.id()}`, m(PollShowcaseItem, {
          key: poll.id(),
          poll: poll
        }));
      });
    });
    return items;
  }
}
flarum.reg.add('fof-polls', 'forum/components/Poll/PollShowcase', PollShowcase);